import { Component } from '@angular/core';
import { SelectFieldComponent } from '@conciso/design-system-angular';

@Component({
  selector: 'app-demo',
  imports: [SelectFieldComponent],
  template: `
    <div style="display:flex;flex-direction:column;gap:var(--s3);max-width:28rem">
        <cds-select-field
            label="Bereich"
            [options]="options"
            fieldId="form-area"
            [formControl]="ctrl">
        </cds-select-field>
        <p style="font:14px/1.4 system-ui,sans-serif;margin:0">
            Wert:
            <strong>{{ ctrl.value || '(leer)' }}</strong>
        </p>
    </div>`,
})
export class DemoComponent {
  options = ['Bitte wählen', 'Corporate', 'Angewandte KI', 'Effektive Software'];
}
